mapper.select:
SELECT ph.point_history_id AS pointHistoryId, ph.point_wallet_id AS pointWalletId, pp.point_provider_name AS providerName, ph.point_type AS pointType, ph.point_amount AS pointAmount, ph.content AS content, DATE_FORMAT(ph.occurred_at, '%Y-%m-%dT%H:%i:%s') AS occurredAt FROM point_history ph JOIN point_wallet pw ON ph.point_wallet_id = pw.point_wallet_id JOIN point_provider pp ON pw.point_provider_id = pp.point_provider_id WHERE ph.member_id = #{memberId}
AND ph.point_wallet_id = #{pointWalletId}
AND ph.point_type = #{pointType}
AND DATE_FORMAT(ph.occurred_at, '%Y-%m') = #{yearMonth}
ORDER BY ph.occurred_at DESC

SELECT pup.point_usage_place_id AS usagePlaceId, pup.point_provider_id AS pointProviderId, pp.point_provider_name AS providerName, pup.place_name AS placeName, pup.category_id AS categoryId, c.category_name AS categoryName, pup.use_yn AS useYn, pup.description AS description FROM point_usage_place pup JOIN point_provider pp ON pup.point_provider_id = pp.point_provider_id LEFT JOIN category c ON pup.category_id = c.category_id WHERE pup.point_provider_id = #{pointProviderId} AND pup.use_yn = 'Y' AND pp.use_yn = 'Y'
AND pup.category_id = #{categoryId}
ORDER BY pup.point_usage_place_id ASC
